package main

import (
	"encoding/json"
	"fmt"
	"os"
)

const dataFile = "todos.json"

// Item is a single todo item.
type Item struct {
	Text string `json:"text"`
	Done bool   `json:"done"`
}

// load reads items from the JSON data file. A missing file yields an empty
// list. A corrupt file is treated as an error.
func load() ([]Item, error) {
	data, err := os.ReadFile(dataFile)
	if err != nil {
		if os.IsNotExist(err) {
			return []Item{}, nil
		}
		return nil, err
	}
	var items []Item
	if err := json.Unmarshal(data, &items); err != nil {
		return nil, err
	}
	return items, nil
}

// save writes items to the JSON data file.
func save(items []Item) error {
	data, err := json.MarshalIndent(items, "", "  ")
	if err != nil {
		return err
	}
	return os.WriteFile(dataFile, data, 0o644)
}

func usage() {
	fmt.Fprintln(os.Stderr, "usage: todo <add <text> | list | done <n>>")
}

func main() {
	if len(os.Args) < 2 {
		usage()
		os.Exit(2)
	}

	items, err := load()
	if err != nil {
		fmt.Fprintf(os.Stderr, "todo: cannot load todos: %v\n", err)
		os.Exit(1)
	}

	switch os.Args[1] {
	case "add":
		if len(os.Args) < 3 {
			usage()
			os.Exit(2)
		}
		items = append(items, Item{Text: os.Args[2], Done: false})
		if err := save(items); err != nil {
			fmt.Fprintf(os.Stderr, "todo: cannot save: %v\n", err)
			os.Exit(1)
		}

	case "list":
		for _, it := range items {
			if it.Done {
				fmt.Printf("[x] %s\n", it.Text)
			} else {
				fmt.Printf("[ ] %s\n", it.Text)
			}
		}

	case "done":
		if len(os.Args) < 3 {
			usage()
			os.Exit(2)
		}
		var n int
		if _, err := fmt.Sscanf(os.Args[2], "%d", &n); err != nil || n < 1 || n > len(items) {
			fmt.Fprintf(os.Stderr, "todo: invalid item number %q\n", os.Args[2])
			os.Exit(1)
		}
		items[n-1].Done = true
		if err := save(items); err != nil {
			fmt.Fprintf(os.Stderr, "todo: cannot save: %v\n", err)
			os.Exit(1)
		}

	default:
		usage()
		os.Exit(2)
	}
}

package main

import (
	"encoding/json"
	"os"
	"path/filepath"
	"testing"
)

// TestLoadSaveRoundTrip verifies that items written with save can be read
// back by load, preserving their text and done state.
func TestLoadSaveRoundTrip(t *testing.T) {
	// Use a temp dir so we never touch a real todos.json in the workspace.
	wd, err := os.Getwd()
	if err != nil {
		t.Fatal(err)
	}
	dir := t.TempDir()
	if err := os.Chdir(dir); err != nil {
		t.Fatal(err)
	}
	defer os.Chdir(wd)
	defer func() { _ = os.Remove(dataFile) }()

	want := []Item{
		{Text: "write tests", Done: false},
		{Text: "ship it", Done: true},
	}
	if err := save(want); err != nil {
		t.Fatalf("save: %v", err)
	}
	got, err := load()
	if err != nil {
		t.Fatalf("load: %v", err)
	}
	if len(got) != len(want) {
		t.Fatalf("got %d items, want %d", len(got), len(want))
	}
	for i := range want {
		if got[i].Text != want[i].Text || got[i].Done != want[i].Done {
			t.Errorf("item %d = %+v, want %+v", i, got[i], want[i])
		}
	}
}

// TestLoadMissingFile verifies that load returns an empty list when no
// todos.json exists yet.
func TestLoadMissingFile(t *testing.T) {
	wd, err := os.Getwd()
	if err != nil {
		t.Fatal(err)
	}
	dir := t.TempDir()
	if err := os.Chdir(dir); err != nil {
		t.Fatal(err)
	}
	defer os.Chdir(wd)

	items, err := load()
	if err != nil {
		t.Fatalf("load: %v", err)
	}
	if items == nil || len(items) != 0 {
		t.Fatalf("expected empty list, got %v", items)
	}
}

// TestMarkDone verifies that marking item n done sets the Done flag and
// round-trips through JSON persistence.
func TestMarkDone(t *testing.T) {
	wd, err := os.Getwd()
	if err != nil {
		t.Fatal(err)
	}
	dir := t.TempDir()
	if err := os.Chdir(dir); err != nil {
		t.Fatal(err)
	}
	defer os.Chdir(wd)
	defer func() { _ = os.Remove(dataFile) }()

	items := []Item{{Text: "a"}, {Text: "b"}, {Text: "c"}}
	if err := save(items); err != nil {
		t.Fatal(err)
	}

	// Mark item 2 done.
	n := 2
	items[n-1].Done = true
	if err := save(items); err != nil {
		t.Fatal(err)
	}

	data, err := os.ReadFile(dataFile)
	if err != nil {
		t.Fatal(err)
	}
	var persisted []Item
	if err := json.Unmarshal(data, &persisted); err != nil {
		t.Fatal(err)
	}
	if !persisted[1].Done {
		t.Fatal("expected item 2 to be marked done")
	}
	if persisted[0].Done || persisted[2].Done {
		t.Fatal("expected other items to remain not done")
	}
}

// TestDataFilePath is a sanity check that the tests exercise the actual file
// path used by the app.
func TestDataFilePath(t *testing.T) {
	want := "todos.json"
	if dataFile != want {
		t.Fatalf("dataFile = %q, want %q", dataFile, want)
	}
	if !filepath.IsAbs(filepath.Join(t.TempDir(), dataFile)) {
		t.Fatal("bad path")
	}
}

