 3	import "strings"
 4	
 5	// Pipeline runs a sequence of stages in order.
 6	//
 7	// A Pipeline is itself a [Stage], so pipelines nest. The assertion below is
 8	// what keeps that true when somebody changes the interface.
 9	type Pipeline struct {
10		stages []Stage
11	}
12	
13	var _ Stage = (*Pipeline)(nil)
14	
15	// New builds a pipeline from stages, in the order they will run.
16	//
17	// The slice is copied so a caller that keeps its own reference cannot reorder
18	// a pipeline that is already running.
19	func New(stages ...Stage) *Pipeline {
20		return &Pipeline{stages: append([]Stage(nil), stages...)}
21	}
22	
23	// Add appends one stage to the end of the pipeline.
24	func (p *Pipeline) Add(s Stage) { p.stages = append(p.stages, s) }
25	
26	// Name implements [Stage]: every stage name joined by "|".
27	func (p *Pipeline) Name() string {
28		parts := make([]string, len(p.stages))
29		for i, s := range p.stages {
30			parts[i] = s.Name()
31		}
32		return strings.Join(parts, "|")
33	}
34	
35	// Process implements [Stage]: each stage in turn, feeding one's output to the
36	// next.
37	func (p *Pipeline) Process(in string) string {
38		for _, s := range p.stages {
39			in = s.Process(in)
40		}
41		return in
42	}

