 1	// Package store is a tiny record store keyed by a label a human typed.
 2	package store
 3	
 4	import "errors"
 5	
 6	// ErrNotFound means nothing is filed under the key.
 7	var ErrNotFound = errors.New("store: not found")
 8	
 9	// Record is one stored value.
10	type Record struct {
11		ID    int
12		Value string
13	}
14	
15	// Store holds records and the index that finds them.
16	//
17	// The store knows nothing about how a key is spelled: that rule belongs to
18	// [Index], so that every caller gets the same one.
19	type Store struct {
20		next    int
21		records map[int]Record
22		idx     *Index
23	}
24	
25	// New returns an empty store.
26	func New() *Store {
27		return &Store{records: make(map[int]Record), idx: NewIndex()}
28	}
29	
30	// Put files value under key and returns the record's id.
31	//
32	// Putting the same key twice replaces the value rather than adding a second
33	// record, whatever the two spellings looked like.
34	func (s *Store) Put(key, value string) int {
35		if id, ok := s.idx.Lookup(key); ok {
36			s.records[id] = Record{ID: id, Value: value}
37			return id
38		}
39		s.next++
40		id := s.next
41		s.records[id] = Record{ID: id, Value: value}
42		s.idx.Add(key, id)
43		return id
44	}
45	
46	// Get returns the record filed under key.
47	func (s *Store) Get(key string) (Record, error) {
48		id, ok := s.idx.Lookup(key)
49		if !ok {
50			return Record{}, ErrNotFound
51		}
52		return s.records[id], nil
53	}
54	
55	// Len reports how many distinct records the store holds.
56	func (s *Store) Len() int { return len(s.records) }

