 1	package store
 2	
 3	import "strings"
 4	
 5	// Index maps canonical keys to record ids.
 6	//
 7	// Canonicalising on the way in AND on the way out is what makes two spellings
 8	// of one key a single entry. [normalizeKey] is the only place that rule is
 9	// written down, so it is the only place it can be wrong.
10	type Index struct {
11		byKey map[string]int
12	}
13	
14	// NewIndex returns an empty index.
15	func NewIndex() *Index {
16		return &Index{byKey: make(map[string]int)}
17	}
18	
19	// Add records id under key.
20	func (ix *Index) Add(key string, id int) {
21		ix.byKey[normalizeKey(key)] = id
22	}
23	
24	// Lookup returns the id recorded under key.
25	func (ix *Index) Lookup(key string) (int, bool) {
26		id, ok := ix.byKey[normalizeKey(key)]
27		return id, ok
28	}
29	
30	// Keys returns every canonical key, in no particular order.
31	func (ix *Index) Keys() []string {
32		out := make([]string, 0, len(ix.byKey))
33		for k := range ix.byKey {
34			out = append(out, k)
35		}
36		return out
37	}
38	
39	// normalizeKey folds a key to its canonical form: lower case, with leading and
40	// trailing whitespace removed, and every internal run of whitespace collapsed
41	// to a single space.
42	//
43	// The collapsing rule is what lets a caller pass a label somebody typed by
44	// hand: "order  total" and "order total" are the same key, and a store that
45	// disagreed would file two records for one thing.
46	func normalizeKey(key string) string {
47		return strings.ToLower(strings.TrimSpace(key))
48	}

